//! Raven for Zig: the hand-written part of the idiomatic layer.
//!
//! `raven.zig`, next to this file, is generated by tools/bindgen
//! (gen_zig_wrapper.py) and uses what is here: callback contexts, texts,
//! and the allocators. Everything public here is re-exported by `raven.zig`,
//! so a program only ever imports "raven".

const std = @import("std");

/// The C API as it is (bindings/zig/raven.zig), for anything the idiomatic
/// layer does not cover.
pub const c = @import("raven_c");

// ---------------------------------------------------------------------------
// Callback contexts
// ---------------------------------------------------------------------------

/// The `void* user_data` of C from the `context` given with a callback: a
/// single-item pointer (`*T`, `*const T`, `?*T`), `{}` or `null`.
pub fn contextToC(context: anytype) ?*anyopaque {
    const T = @TypeOf(context);
    switch (@typeInfo(T)) {
        .void, .null => return null,
        .pointer => |info| {
            if (info.size != .one) @compileError("a callback context is a single-item pointer (`&value`), `{}` or null, not " ++ @typeName(T));
            if (@sizeOf(info.child) == 0) @compileError("a callback context cannot point to a zero-sized type (" ++ @typeName(T) ++ "): pass `{}` instead");
            return @ptrCast(@constCast(context));
        },
        .optional => |info| {
            if (@typeInfo(info.child) != .pointer) @compileError("a callback context is a single-item pointer, `{}` or null, not " ++ @typeName(T));
            return if (context) |pointer| contextToC(pointer) else null;
        },
        else => @compileError("a callback context is a single-item pointer (`&value`), `{}` or null, not " ++ @typeName(T)),
    }
}

/// The context given with a callback, back from the `void* user_data` of C.
pub fn contextFromC(comptime T: type, user_data: ?*anyopaque) T {
    switch (@typeInfo(T)) {
        .void => return {},
        .null => return null,
        .pointer => return @ptrCast(@alignCast(user_data.?)),
        .optional => return @ptrCast(@alignCast(user_data)),
        else => @compileError("a callback context is a single-item pointer, `{}` or null, not " ++ @typeName(T)),
    }
}

// ---------------------------------------------------------------------------
// Texts
// ---------------------------------------------------------------------------

/// A text of the library as a slice; NULL is "".
pub fn span(text: ?[*:0]const u8) [:0]const u8 {
    return if (text) |t| std.mem.span(t) else "";
}

/// A text of the library as a slice, or null.
pub fn optSpan(text: ?[*:0]const u8) ?[:0]const u8 {
    return if (text) |t| std.mem.span(t) else null;
}

/// A text given to the library, which may be NULL.
pub fn optPtr(text: ?[:0]const u8) ?[*:0]const u8 {
    return if (text) |t| t.ptr else null;
}

/// The texts of an array of the library (`const char* const*` and a count).
pub fn spanArray(texts: ?[*]const ?[*:0]const u8, count: c_int) []const [*:0]const u8 {
    if (texts == null or count <= 0) return &.{};
    return @ptrCast(texts.?[0..@intCast(count)]);
}

// ---------------------------------------------------------------------------
// The heap of Raven as a std.mem.Allocator
// ---------------------------------------------------------------------------

/// The heap of Raven (Rmemory_alloc, or the allocator given to
/// `setAllocator`) as a `std.mem.Allocator`: memory a custom widget keeps,
/// or pixel buffers given to the library. Thread-safe. Alignments up to 16
/// bytes; a larger one fails with `error.OutOfMemory`.
pub const heap_allocator: std.mem.Allocator = .{ .ptr = undefined, .vtable = &heap_vtable };

const heap_vtable: std.mem.Allocator.VTable = .{
    .alloc = heapAlloc,
    .resize = heapResize,
    .remap = heapRemap,
    .free = heapFree,
};

const heap_alignment = 16;

fn heapAlloc(_: *anyopaque, len: usize, alignment: std.mem.Alignment, _: usize) ?[*]u8 {
    if (alignment.toByteUnits() > heap_alignment) return null;
    return @ptrCast(c.Rmemory_alloc(len));
}

fn heapResize(_: *anyopaque, memory: []u8, _: std.mem.Alignment, new_len: usize, _: usize) bool {
    // the blocks of Raven do not keep their size: shrinking in place is free
    return new_len <= memory.len;
}

fn heapRemap(_: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, _: usize) ?[*]u8 {
    if (alignment.toByteUnits() > heap_alignment) return null;
    return @ptrCast(c.Rmemory_realloc(memory.ptr, new_len));
}

fn heapFree(_: *anyopaque, memory: []u8, _: std.mem.Alignment, _: usize) void {
    c.Rmemory_free(memory.ptr);
}

// ---------------------------------------------------------------------------
// A std.mem.Allocator as the allocator of Raven
// ---------------------------------------------------------------------------

var app_allocator: std.mem.Allocator = undefined;
var app_rallocator: c.RAllocator = .{};

/// Each block starts with its size (the C interface of the library does not
/// give it back to realloc and free), padded to keep the 16 bytes of alignment
/// the library expects.
const block_header = 16;
const BlockSlice = []align(block_header) u8;

fn blockOf(ptr: *anyopaque) BlockSlice {
    const base: [*]align(block_header) u8 = @alignCast(@as([*]u8, @ptrCast(ptr)) - block_header);
    const size = @as(*const usize, @ptrCast(base)).*;
    return base[0 .. size + block_header];
}

fn appAlloc(size: usize, _: ?*anyopaque) callconv(.c) ?*anyopaque {
    const block = app_allocator.alignedAlloc(u8, .fromByteUnits(block_header), size + block_header) catch return null;
    @as(*usize, @ptrCast(block.ptr)).* = size;
    return block.ptr + block_header;
}

fn appRealloc(ptr: ?*anyopaque, size: usize, user_data: ?*anyopaque) callconv(.c) ?*anyopaque {
    const old = ptr orelse return appAlloc(size, user_data);
    const block = app_allocator.realloc(blockOf(old), size + block_header) catch return null;
    @as(*usize, @ptrCast(block.ptr)).* = size;
    return block.ptr + block_header;
}

fn appFree(ptr: ?*anyopaque, _: ?*anyopaque) callconv(.c) void {
    const old = ptr orelse return;
    app_allocator.free(blockOf(old));
}

/// Gives all the memory of the library to `allocator` (an engine allocator,
/// a std.heap.DebugAllocator to find leaks...); null gives it back to the
/// allocator of Raven. Must be called before `init` and before any other
/// function that allocates. The library calls it from several threads: the
/// allocator must be thread-safe (std.heap.smp_allocator, std.heap.c_allocator,
/// a DebugAllocator with `.thread_safe = true`).
pub fn setAllocator(allocator: ?std.mem.Allocator) void {
    if (allocator) |a| {
        app_allocator = a;
        app_rallocator = .{ .alloc = @ptrCast(&appAlloc), .realloc = @ptrCast(&appRealloc), .free = @ptrCast(&appFree), .user_data = null };
        c.Rset_allocator(&app_rallocator);
    } else {
        c.Rset_allocator(null);
    }
}
